// ============================================================
// Robust extraction — handles parsed object OR raw string JSON.
// Falls back gracefully so the webhook always gets a response.
// ============================================================
try {
  const raw = $input.first().json;

  let parsed = raw.output;

  if (typeof parsed === 'string') {
    const cleaned = parsed.replace(/```json|```/g, '').trim();
    const match = cleaned.match(/\{[\s\S]*\}/);
    parsed = match ? JSON.parse(match[0]) : {};
  }

  if (!parsed || typeof parsed !== 'object') {
    parsed = {};
  }

  const botReply  = parsed.bot_reply || "I'm here to help! Could you please repeat your message?";
  const email     = (parsed.email     || "").trim();
  const name      = (parsed.name      || "").trim();
  const whatsapp  = (parsed.whatsapp  || "").trim();
  const service   = (parsed.service   || "").trim();
  const budget    = (parsed.budget    || "").trim();
  const contact   = (parsed.contact   || "").trim();
  const sessionId = $('Webhook').first().json.body?.sessionId || "";

  const isComplete = botReply.toLowerCase().includes("you'll hear from our team");

  return {
    json: {
      name, email, whatsapp, service, budget,
      contactOn: contact,
      output: botReply,
      isComplete,
      sessionId,
      hasEmail: email.length > 0
    }
  };

} catch (err) {
  const sessionId = $('Webhook').first().json.body?.sessionId || "";
  return {
    json: {
      name: "", email: "", whatsapp: "", service: "", budget: "", contactOn: "",
      output: "I apologize for a brief technical issue. Could you please resend your last message?",
      isComplete: false,
      sessionId,
      hasEmail: false,
      parseError: err.message
    }
  };
}

// ============================================================
// Build Response — safe on all 3 paths:
//   1. Mid-conversation  (If Conversation Complete → FALSE)
//   2. Completed flow    (inform admin → Build Response)
//   3. AI Agent error    (AI Agent Error Handler → Build Response)
//
// Uses $input.first().json which always has data from the
// direct predecessor, regardless of which path was taken.
// ============================================================
try {
  const inputData = $input.first().json;

  const response  = inputData.output
                 || inputData.response
                 || "Thank you for contacting us!";

  const sessionId = inputData.sessionId || "";

  return {
    json: {
      status: "success",
      response,
      sessionId
    }
  };

} catch (err) {
  return {
    json: {
      status: "error",
      response: "Thank you for reaching out! Our team will contact you shortly.",
      sessionId: ""
    }
  };
}

// AI Agent Error Handler
// Triggered ONLY when Gemini API fails (rate limit, timeout, etc.)
// Outputs same shape as Extract Inquiry Details so Build Response
// can read it uniformly via $input.
const sessionId = $('Webhook').first().json.body?.sessionId || "";

return {
  json: {
    name: "", email: "", whatsapp: "", service: "", budget: "", contactOn: "",
    output: "I apologize for a brief technical issue. Please try again in a moment, or reach us directly at [Your Email]",
    isComplete: false,
    sessionId,
    hasEmail: false,
    isAgentError: true
  }
};
